<h2>Canvas Shapes</h2>  
<canvas id="c1" width="600" height="400" style="border:1px solid black;"></canvas>
<script>  
var canvas = document.getElementById("c1");  
var ctx = canvas.getContext("2d");  
// line  
ctx.beginPath();  
ctx.moveTo(20, 20);  
ctx.lineTo(150, 20);  
ctx.stroke();  
// rectangle  
ctx.strokeRect(20, 40, 100, 60);  
// square (filled)  
ctx.fillStyle = "green";  
ctx.fillRect(150, 40, 60, 60);  
