Aim: Develop Square, Rectangle, Line, Circle, Text, Linear & Circular gradient, Image in canvas, Arc
graphical shapes using HTML 5 canvas and HTML5 SVG.

// arc  
ctx.beginPath();  
ctx.arc(400, 70, 40, 0, Math.PI);  
ctx.strokeStyle = "purple";  
ctx.stroke();  
// text  
ctx.font = "20px Arial";  
ctx.fillStyle = "black";  
ctx.fillText("Hello Canvas", 470, 75);  
// linear gradient  
var lg = ctx.createLinearGradient(20, 150, 220, 150);
lg.addColorStop(0, "yellow");  
lg.addColorStop(1, "orange");  
ctx.fillStyle = lg;  
ctx.fillRect(20, 150, 200, 70);  
// circular gradient  
var rg = ctx.createRadialGradient(330, 190, 10, 330, 190, 50);
rg.addColorStop(0, "white");  
rg.addColorStop(1, "blue");  
ctx.fillStyle = rg;  
ctx.beginPath();  
ctx.arc(330, 190, 50, 0, 2 * Math.PI);  
ctx.fill();  
// image in canvas  
var img = new Image();  
img.src = "sample.jpg";  
img.onload = function() {  
ctx.drawImage(img, 450, 140, 100, 100);  
};  
</script>  
